22	func newCleanCmd() *cobra.Command {
23		var forceFlag bool
24		var allFlag bool
25		var dryRunFlag bool
26		var sessionFlag string
27	
28		cmd := &cobra.Command{
29			Use:   "clean",
30			Short: "Clean up session data and orphaned Entire data",
31			Long: `Clean up Entire session data for the current HEAD commit.
32	
33	By default, cleans session state and shadow branches for the current HEAD:
34	  - Session state files (.git/entire-sessions/<session-id>.json)
35	  - Shadow branch (entire/<commit-hash>-<worktree-hash>)
36	
37	Use --all to clean all orphaned Entire data across the repository:
38	  - Orphaned shadow branches
39	  - Orphaned session state files
40	  - Orphaned checkpoint entries on entire/checkpoints/v1
41	  - Temporary files (.entire/tmp/)
42	The entire/checkpoints/v1 branch itself is preserved.
43	
44	Use --session <id> to clean a specific session only.
45	
46	Without --force, prompts for confirmation before deleting.
47	Use --dry-run to preview what would be deleted without prompting.`,
48			RunE: func(cmd *cobra.Command, _ []string) error {
49				ctx := cmd.Context()
50	
51				// Validate mutually exclusive flags
52				if allFlag && sessionFlag != "" {
53					return errors.New("--all and --session cannot be used together")
54				}
55	
56				// Check if in git repository before initializing logging,
57				// to avoid creating .entire/logs in arbitrary directories.
58				if _, err := paths.WorktreeRoot(ctx); err != nil {
59					return errors.New("not a git repository")
60				}
61	
62				// Initialize logging
63				logging.SetLogLevelGetter(GetLogLevel)
64				if err := logging.Init(ctx, ""); err == nil {
65					defer logging.Close()
66				}
67	
68				if allFlag {
69					return runCleanAll(ctx, cmd, forceFlag, dryRunFlag)
70				}
71	
72				if sessionFlag != "" {
73					strat := GetStrategy(ctx)
74					return runCleanSession(ctx, cmd, strat, sessionFlag, forceFlag, dryRunFlag, "Clean", "cleaned")
75				}
76	
77				return runCleanCurrentHead(ctx, cmd, forceFlag, dryRunFlag)
78			},
79		}
80	
81		cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Skip confirmation prompt and override active session guard")
82		cmd.Flags().BoolVarP(&allFlag, "all", "a", false, "Clean all orphaned data across the repository")
83		cmd.Flags().BoolVarP(&dryRunFlag, "dry-run", "d", false, "Preview what would be deleted without deleting")
84		cmd.Flags().StringVar(&sessionFlag, "session", "", "Clean a specific session by ID")
85	
86		return cmd
87	}
88	
89	// runCleanCurrentHead cleans session data for the current HEAD commit.
90	func runCleanCurrentHead(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
91		strat := GetStrategy(ctx)
92		w := cmd.OutOrStdout()
93	
94		// Dry-run: show what would be cleaned
95		if dryRun {
96			return previewCurrentHead(ctx, w)
97		}
98	
99		// Check for active sessions before cleaning
100		if !force {
101			activeSessions, err := activeSessionsOnCurrentHead(ctx)
102			if err != nil {
103				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not check for active sessions: %v\n", err)
104				fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override.")
105				return nil
106			}
107			if len(activeSessions) > 0 {
108				fmt.Fprintln(cmd.ErrOrStderr(), "Active sessions detected on current HEAD:")
109				for _, s := range activeSessions {
110					fmt.Fprintf(cmd.ErrOrStderr(), "  %s (phase: %s)\n", s.SessionID, s.Phase)
111				}
112				fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override or wait for sessions to finish.")
113				return nil
114			}
115		}
116	
117		// Prompt for confirmation
118		if !force {
119			var confirmed bool
120	
121			form := NewAccessibleForm(
122				huh.NewGroup(
123					huh.NewConfirm().
124						Title("Clean session data for current HEAD?").
125						Value(&confirmed),
126				),
127			)
128	
129			if err := form.Run(); err != nil {
130				if errors.Is(err, huh.ErrUserAborted) {
131					return nil
132				}
133				return fmt.Errorf("failed to get confirmation: %w", err)
134			}
135	
136			if !confirmed {
137				return nil
138			}
139		}
140	
141		if err := strat.Reset(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr()); err != nil {
142			return fmt.Errorf("clean failed: %w", err)
143		}
144	
145		return nil
146	}
