148	// previewCurrentHead shows what would be cleaned for the current HEAD.
149	func previewCurrentHead(ctx context.Context, w io.Writer) error {
150		repo, err := openRepository(ctx)
151		if err != nil {
152			return err
153		}
154	
155		head, err := repo.Head()
156		if err != nil {
157			return fmt.Errorf("failed to get HEAD: %w", err)
158		}
159	
160		worktreePath, err := paths.WorktreeRoot(ctx)
161		if err != nil {
162			return fmt.Errorf("failed to get worktree path: %w", err)
163		}
164		worktreeID, err := paths.GetWorktreeID(worktreePath)
165		if err != nil {
166			return fmt.Errorf("failed to get worktree ID: %w", err)
167		}
168	
169		shadowBranchName := checkpoint.ShadowBranchNameForCommit(head.Hash().String(), worktreeID)
170	
171		// Check if shadow branch exists
172		refName := plumbing.NewBranchReferenceName(shadowBranchName)
173		_, refErr := repo.Reference(refName, true)
174		hasShadowBranch := refErr == nil
175	
176		// Find sessions for this commit
177		strat := GetStrategy(ctx)
178		sessions, err := strat.FindSessionsForCommit(ctx, head.Hash().String())
179		if err != nil {
180			sessions = nil
181		}
182	
183		if !hasShadowBranch && len(sessions) == 0 {
184			fmt.Fprintln(w, "Nothing to clean for current HEAD.")
185			return nil
186		}
187	
188		fmt.Fprint(w, "Would clean the following items:\n\n")
189	
190		if len(sessions) > 0 {
191			fmt.Fprintf(w, "Session states (%d):\n", len(sessions))
192			for _, s := range sessions {
193				fmt.Fprintf(w, "  %s (checkpoints: %d)\n", s.SessionID, s.StepCount)
194			}
195			fmt.Fprintln(w)
196		}
197	
198		if hasShadowBranch {
199			fmt.Fprintf(w, "Shadow branch:\n  %s\n\n", shadowBranchName)
200		}
201	
202		fmt.Fprintln(w, "Run without --dry-run to clean these items.")
203		return nil
204	}
