260	// runCleanAll cleans all orphaned data across the repository (old `entire clean` behavior).
261	func runCleanAll(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
262		// List all cleanup items
263		items, err := strategy.ListAllCleanupItems(ctx)
264		if err != nil {
265			return fmt.Errorf("failed to list orphaned items: %w", err)
266		}
267	
268		// List temp files
269		tempFiles, err := listTempFiles(ctx)
270		if err != nil {
271			// Non-fatal: continue with other cleanup items
272			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to list temp files: %v\n", err)
273		}
274	
275		return runCleanAllWithItems(ctx, cmd, force, dryRun, items, tempFiles)
276	}
277	
278	// runCleanAllWithItems is the core logic for cleaning all orphaned items.
279	// Separated for testability — tests pass a cmd without a TTY and use force or dryRun to avoid prompts.
280	func runCleanAllWithItems(ctx context.Context, cmd *cobra.Command, force, dryRun bool, items []strategy.CleanupItem, tempFiles []string) error {
281		w := cmd.OutOrStdout()
282		errW := cmd.ErrOrStderr()
283		// Handle no items case
284		if len(items) == 0 && len(tempFiles) == 0 {
285			fmt.Fprintln(w, "No orphaned items to clean up.")
286			return nil
287		}
288	
289		// Group items by type for display
290		var branches, states, checkpoints []strategy.CleanupItem
291		for _, item := range items {
292			switch item.Type {
293			case strategy.CleanupTypeShadowBranch:
294				branches = append(branches, item)
295			case strategy.CleanupTypeSessionState:
296				states = append(states, item)
297			case strategy.CleanupTypeCheckpoint:
298				checkpoints = append(checkpoints, item)
299			}
300		}
301	
302		// Show preview when not in force mode
303		if !force || dryRun {
304			totalItems := len(items) + len(tempFiles)
305			fmt.Fprintf(w, "Found %d %s to clean:\n\n", totalItems, itemWord(totalItems))
306	
307			if len(branches) > 0 {
308				fmt.Fprintf(w, "Shadow branches (%d):\n", len(branches))
309				for _, item := range branches {
310					fmt.Fprintf(w, "  %s\n", item.ID)
311				}
312				fmt.Fprintln(w)
313			}
314	
315			if len(states) > 0 {
316				fmt.Fprintf(w, "Session states (%d):\n", len(states))
317				for _, item := range states {
318					fmt.Fprintf(w, "  %s\n", item.ID)
319				}
320				fmt.Fprintln(w)
321			}
322	
323			if len(checkpoints) > 0 {
324				fmt.Fprintf(w, "Checkpoint metadata (%d):\n", len(checkpoints))
325				for _, item := range checkpoints {
326					fmt.Fprintf(w, "  %s\n", item.ID)
327				}
328				fmt.Fprintln(w)
329			}
330	
331			if len(tempFiles) > 0 {
332				fmt.Fprintf(w, "Temp files (%d):\n", len(tempFiles))
333				for _, file := range tempFiles {
334					fmt.Fprintf(w, "  %s\n", file)
335				}
336				fmt.Fprintln(w)
337			}
338	
339			if dryRun {
340				fmt.Fprintln(w, "Run without --dry-run to delete these items.")
341				return nil
342			}
343	
344			// Prompt for confirmation
345			var confirmed bool
346			form := NewAccessibleForm(
347				huh.NewGroup(
348					huh.NewConfirm().
349						Title(fmt.Sprintf("Delete %d %s?", totalItems, itemWord(totalItems))).
350						Value(&confirmed),
351				),
352			)
353			if err := form.Run(); err != nil {
354				if errors.Is(err, huh.ErrUserAborted) {
355					return nil
356				}
357				return fmt.Errorf("failed to get confirmation: %w", err)
358			}
359			if !confirmed {
360				return nil
361			}
362		}
363	
364		// Force mode - delete items
365		result, err := strategy.DeleteAllCleanupItems(ctx, items)
366		if err != nil {
367			return fmt.Errorf("failed to delete orphaned items: %w", err)
368		}
369	
370		// Delete temp files
371		deletedTempFiles, failedTempFiles := deleteTempFiles(ctx, tempFiles)
372	
373		// Report results
374		totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints) + len(deletedTempFiles)
375		totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints) + len(failedTempFiles)
376	
377		if totalDeleted > 0 {
378			fmt.Fprintf(w, "✓ Deleted %d %s:\n", totalDeleted, itemWord(totalDeleted))
379	
380			if len(result.ShadowBranches) > 0 {
381				fmt.Fprintf(w, "\nShadow branches (%d):\n", len(result.ShadowBranches))
382				for _, branch := range result.ShadowBranches {
383					fmt.Fprintf(w, "  %s\n", branch)
384				}
385			}
386	
387			if len(result.SessionStates) > 0 {
388				fmt.Fprintf(w, "\nSession states (%d):\n", len(result.SessionStates))
389				for _, state := range result.SessionStates {
390					fmt.Fprintf(w, "  %s\n", state)
391				}
392			}
393	
394			if len(result.Checkpoints) > 0 {
395				fmt.Fprintf(w, "\nCheckpoints (%d):\n", len(result.Checkpoints))
396				for _, cp := range result.Checkpoints {
397					fmt.Fprintf(w, "  %s\n", cp)
398				}
399			}
400	
401			if len(deletedTempFiles) > 0 {
402				fmt.Fprintf(w, "\nTemp files (%d):\n", len(deletedTempFiles))
403				for _, file := range deletedTempFiles {
404					fmt.Fprintf(w, "  %s\n", file)
405				}
406			}
407		}
408	
409		if totalFailed > 0 {
410			fmt.Fprintf(errW, "\nFailed to delete %d %s:\n", totalFailed, itemWord(totalFailed))
411	
412			if len(result.FailedBranches) > 0 {
413				fmt.Fprintf(errW, "\nShadow branches:\n")
414				for _, branch := range result.FailedBranches {
415					fmt.Fprintf(errW, "  %s\n", branch)
416				}
417			}
418	
419			if len(result.FailedStates) > 0 {
420				fmt.Fprintf(errW, "\nSession states:\n")
421				for _, state := range result.FailedStates {
422					fmt.Fprintf(errW, "  %s\n", state)
423				}
424			}
425	
426			if len(result.FailedCheckpoints) > 0 {
427				fmt.Fprintf(errW, "\nCheckpoints:\n")
428				for _, cp := range result.FailedCheckpoints {
429					fmt.Fprintf(errW, "  %s\n", cp)
430				}
431			}
432	
433			if len(failedTempFiles) > 0 {
434				fmt.Fprintf(errW, "\nTemp files:\n")
435				for _, fe := range failedTempFiles {
436					fmt.Fprintf(errW, "  %s: %v\n", fe.File, fe.Err)
437				}
438			}
439	
440			return fmt.Errorf("failed to delete %d %s", totalFailed, itemWord(totalFailed))
441		}
442	
443		return nil
444	}
445	
446	// listTempFiles returns files in .entire/tmp/ that are safe to delete,
447	// excluding files belonging to active sessions.
448	// Uses os.DirFS + fs.WalkDir to confine listing to the temp directory.
449	func listTempFiles(ctx context.Context) ([]string, error) {
450		absDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
451		if err != nil {
452			return nil, fmt.Errorf("failed to resolve temp dir: %w", err)
453		}
454		root, err := os.OpenRoot(absDir)
455		if err != nil {
456			if os.IsNotExist(err) {
457				return nil, nil
458			}
459			return nil, fmt.Errorf("failed to open root: %w", err)
460		}
461		defer root.Close()
462	
463		// Build set of active session IDs to protect their temp files
464		activeSessionIDs := make(map[string]bool)
465		if states, listErr := strategy.ListSessionStates(ctx); listErr == nil {
466			for _, state := range states {
467				activeSessionIDs[state.SessionID] = true
468			}
469		}
470	
471		var files []string
472		err = fs.WalkDir(root.FS(), ".", func(_ string, d fs.DirEntry, err error) error {
473			if err != nil {
474				return err
475			}
476			if d.IsDir() {
477				return nil
478			}
479			// Skip temp files belonging to active sessions (e.g., "session-id.json")
480			name := d.Name()
481			sessionID := strings.TrimSuffix(name, ".json")
482			if sessionID != name && activeSessionIDs[sessionID] {
483				return nil
484			}
485			files = append(files, name)
486			return nil
487		})
488		if os.IsNotExist(err) {
489			return nil, nil
490		}
491		if err != nil {
492			return nil, fmt.Errorf("failed to list temp dir: %w", err)
493		}
494		return files, nil
495	}
496	
497	// TempFileDeleteError contains a file name and the error that occurred during deletion.
498	type TempFileDeleteError struct {
499		File string
500		Err  error
501	}
502	
503	// deleteTempFiles removes all files in .entire/tmp/.
504	// Uses os.Root to ensure deletions are confined to the temp directory.
505	// Returns successfully deleted files and any failures with their error reasons.
506	func deleteTempFiles(ctx context.Context, files []string) (deleted []string, failed []TempFileDeleteError) {
507		absDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
508		if err != nil {
509			for _, file := range files {
510				failed = append(failed, TempFileDeleteError{File: file, Err: err})
511			}
512			return nil, failed
513		}
514		root, err := os.OpenRoot(absDir)
515		if err != nil {
516			for _, file := range files {
517				failed = append(failed, TempFileDeleteError{File: file, Err: err})
518			}
519			return nil, failed
520		}
521		defer root.Close()
522	
523		for _, file := range files {
524			if err := root.Remove(file); err != nil {
525				failed = append(failed, TempFileDeleteError{File: file, Err: err})
526			} else {
527				deleted = append(deleted, file)
528			}
529		}
530		return deleted, failed
531	}
532	
533	// activeSessionsOnCurrentHead returns sessions on the current HEAD
534	// that are in an active phase (ACTIVE).
535	func activeSessionsOnCurrentHead(ctx context.Context) ([]*session.State, error) {
536		repo, err := openRepository(ctx)
537		if err != nil {
538			return nil, err
539		}
540	
541		head, err := repo.Head()
542		if err != nil {
543			return nil, fmt.Errorf("failed to get HEAD: %w", err)
544		}
545		currentHead := head.Hash().String()
546	
547		states, err := strategy.ListSessionStates(ctx)
548		if err != nil {
549			return nil, fmt.Errorf("failed to list session states: %w", err)
550		}
551	
552		var active []*session.State
553		for _, state := range states {
554			if state.BaseCommit != currentHead {
555				continue
556			}
557			if state.Phase.IsActive() {
558				active = append(active, state)
559			}
560		}
561	
562		return active, nil
563	}
564	
565	// itemWord returns "item" or "items" based on count.
566	func itemWord(n int) string {
567		if n == 1 {
568			return "item"
569		}
570		return "items"
571	}
