59			Short: "Stop one or more active sessions",
60			Long: `Mark one or more active sessions as ended.
61	
62	Fires EventSessionStop through the state machine with a no-op action handler,
63	so no condensation or checkpoint-writing occurs. To flush pending work, commit first.
64	
65	Examples:
66	  entire sessions stop                     No sessions: exits. One session: confirm and stop. Multiple: show selector
67	  entire sessions stop <session-id>        Stop a specific session by ID
68	  entire sessions stop --all               Stop all active sessions
69	  entire sessions stop --force             Skip confirmation prompt`,
70			Args: cobra.MaximumNArgs(1),
71			RunE: func(cmd *cobra.Command, args []string) error {
72				ctx := cmd.Context()
73	
74				var sessionID string
75				if len(args) > 0 {
76					sessionID = args[0]
77				}
78	
79				if allFlag && sessionID != "" {
80					return errors.New("--all and session ID argument are mutually exclusive")
81				}
82	
83				return runStop(ctx, cmd, sessionID, allFlag, forceFlag)
84			},
85		}
86	
87		cmd.Flags().BoolVar(&allFlag, "all", false, "Stop all active sessions")
88		cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Skip confirmation prompt")
89	
90		return cmd
91	}
