130	// filterActiveSessions returns sessions that have not been explicitly ended.
131	// A session is considered ended if Phase == PhaseEnded OR EndedAt is set.
132	// This matches the logic in status.go's writeActiveSessions for consistency:
133	// any session visible in `entire status` should also be visible in `sessions stop`.
134	func filterActiveSessions(states []*strategy.SessionState) []*strategy.SessionState {
135		var active []*strategy.SessionState
136		for _, s := range states {
