182	  entire sessions list    List all sessions across all worktrees`,
183			RunE: func(cmd *cobra.Command, _ []string) error {
184				return runSessionList(cmd.Context(), cmd)
185			},
186		}
187	
188		return cmd
189	}
190	
191	func runSessionList(ctx context.Context, cmd *cobra.Command) error {
192		states, err := strategy.ListSessionStates(ctx)
193		if err != nil {
194			return fmt.Errorf("failed to list sessions: %w", err)
195		}
196	
197		var filtered []*strategy.SessionState
198		for _, s := range states {
199			if s != nil {
200				filtered = append(filtered, s)
201			}
202		}
203	
204		w := cmd.OutOrStdout()
205	
206		if len(filtered) == 0 {
207			fmt.Fprintln(w, "No sessions.")
208			return nil
209		}
210	
211		// Sort by StartedAt descending (newest first)
212		sort.Slice(filtered, func(i, j int) bool {
213			return filtered[i].StartedAt.After(filtered[j].StartedAt)
214		})
215	
216		sty := newStatusStyles(w)
217	
218		fmt.Fprintln(w, sty.sectionRule("Sessions", sty.width))
219		fmt.Fprintln(w)
220	
221		for _, s := range filtered {
222			writeSessionCard(w, s, sty)
223		}
224	
225		// Footer
226		fmt.Fprintln(w, sty.horizontalRule(sty.width))
227		if len(filtered) == 1 {
228			fmt.Fprintln(w, sty.render(sty.dim, "1 session"))
229		} else {
230			fmt.Fprintln(w, sty.render(sty.dim, fmt.Sprintf("%d sessions", len(filtered))))
231		}
232		fmt.Fprintln(w)
233	
234		return nil
235	}
236	
237	// writeSessionCard renders a single session in status-style card format.
238	func writeSessionCard(w io.Writer, s *strategy.SessionState, sty statusStyles) {
239		agentLabel := string(s.AgentType)
240		if agentLabel == "" {
241			agentLabel = "(unknown)"
242		}
243		wt := sessionWorktreeLabel(s)
244	
245		// Line 1: Agent · Model · worktree · session <id> [· checkpoint <id>]
246		fmt.Fprint(w, sty.render(sty.agent, agentLabel))
247		if s.ModelName != "" {
248			fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), sty.render(sty.dim, s.ModelName))
249		}
250		fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), wt)
251		fmt.Fprintf(w, " %s session %s", sty.render(sty.dim, "·"), s.SessionID)
252		if s.LastCheckpointID != "" {
253			fmt.Fprintf(w, " %s checkpoint %s", sty.render(sty.dim, "·"), string(s.LastCheckpointID))
254		}
255		fmt.Fprintln(w)
256	
257		// Line 2: > "prompt" (truncated)
258		if s.LastPrompt != "" {
259			prompt := stringutil.TruncateRunes(s.LastPrompt, 60, "...")
260			fmt.Fprintf(w, "%s \"%s\"\n", sty.render(sty.dim, ">"), prompt)
261		}
262	
263		// Line 3: status · started X ago · active X ago · tokens X.Xk
264		var stats []string
265		stats = append(stats, sessionPhaseLabel(s))
266		stats = append(stats, "started "+timeAgo(s.StartedAt))
267		if s.LastInteractionTime != nil && s.LastInteractionTime.Sub(s.StartedAt) > time.Minute {
268			stats = append(stats, activeTimeDisplay(s.LastInteractionTime))
269		}
270		tokens := "0"
271		if s.TokenUsage != nil {
272			tokens = formatTokenCount(totalTokens(s.TokenUsage))
273		}
274		stats = append(stats, "tokens "+tokens)
275		statsLine := strings.Join(stats, sty.render(sty.dim, " · "))
276		fmt.Fprintln(w, sty.render(sty.dim, statsLine))
277		fmt.Fprintln(w)
278	}
