281		var jsonFlag bool
282	
283		cmd := &cobra.Command{
284			Use:   "info <session-id>",
285			Short: "Show detailed session information",
286			Long: `Display detailed state for a session.
287	
288	Shows agent, model, status, worktree, timing, token usage, checkpoint linkage,
