305	func runSessionInfo(ctx context.Context, cmd *cobra.Command, sessionID string, jsonOutput bool) error {
306		state, err := strategy.LoadSessionState(ctx, sessionID)
307		if err != nil {
308			return fmt.Errorf("failed to load session: %w", err)
