324	// sessionInfoJSON is the JSON output structure for sessions info --json.
325	type sessionInfoJSON struct {
326		SessionID      string         `json:"session_id"`
327		Agent          string         `json:"agent"`
328		Model          string         `json:"model,omitempty"`
329		Status         string         `json:"status"`
330		WorktreeID     string         `json:"worktree_id,omitempty"`
