336		Checkpoints    int            `json:"checkpoints"`
337		LastCheckpoint string         `json:"last_checkpoint_id,omitempty"`
338		Tokens         *tokenInfoJSON `json:"tokens,omitempty"`
339		LastPrompt     string         `json:"last_prompt,omitempty"`
340		FilesTouched   []string       `json:"files_touched,omitempty"`
