351	func writeSessionInfoJSON(w io.Writer, state *strategy.SessionState, status string) error {
352		agentLabel := string(state.AgentType)
353		if agentLabel == "" {
354			agentLabel = unknownPlaceholder
355		}
356		info := sessionInfoJSON{
357			SessionID:      state.SessionID,
358			Agent:          agentLabel,
359			Model:          state.ModelName,
360			Status:         status,
361			WorktreeID:     state.WorktreeID,
362			WorktreePath:   state.WorktreePath,
363			StartedAt:      state.StartedAt,
364			EndedAt:        state.EndedAt,
365			LastActive:     state.LastInteractionTime,
366			Turns:          state.SessionTurnCount,
367			Checkpoints:    state.StepCount,
368			LastCheckpoint: string(state.LastCheckpointID),
369			LastPrompt:     state.LastPrompt,
370			FilesTouched:   state.FilesTouched,
371		}
372		if state.TokenUsage != nil {
373			info.Tokens = &tokenInfoJSON{
374				Total:      totalTokens(state.TokenUsage),
375				Input:      state.TokenUsage.InputTokens,
376				CacheRead:  state.TokenUsage.CacheReadTokens,
377				CacheWrite: state.TokenUsage.CacheCreationTokens,
378				Output:     state.TokenUsage.OutputTokens,
379			}
380		}
381	
382		enc := json.NewEncoder(w)
383		enc.SetIndent("", "  ")
384		if err := enc.Encode(info); err != nil {
385			return fmt.Errorf("failed to encode session info: %w", err)
386		}
387		return nil
388	}
