405		fmt.Fprintf(w, "Worktree:    %s\n", wt)
406	
407		fmt.Fprintf(w, "Started:     %s (%s)\n",
408			state.StartedAt.Local().Format("2006-01-02 15:04"), timeAgo(state.StartedAt))
409	
410		if state.EndedAt != nil {
411			fmt.Fprintf(w, "Ended:       %s (%s)\n",
412				state.EndedAt.Local().Format("2006-01-02 15:04"), timeAgo(*state.EndedAt))
413		}
414	
415		if state.LastInteractionTime != nil {
416			fmt.Fprintf(w, "Last active: %s (%s)\n",
417				state.LastInteractionTime.Local().Format("2006-01-02 15:04"),
