467	// runStopSession stops a single session by ID, with optional confirmation.
468	func runStopSession(ctx context.Context, cmd *cobra.Command, sessionID string, force bool) error {
469		state, err := strategy.LoadSessionState(ctx, sessionID)
470		if err != nil {
471			return fmt.Errorf("failed to load session: %w", err)
472		}
473		if state == nil {
474			cmd.SilenceUsage = true
475			fmt.Fprintln(cmd.ErrOrStderr(), "Session not found.")
476			return NewSilentError(fmt.Errorf("session not found: %s", sessionID))
477		}
478	
479		if state.Phase == session.PhaseEnded || state.EndedAt != nil {
480			fmt.Fprintf(cmd.OutOrStdout(), "Session %s is already stopped.\n", sessionID)
481			return nil
482		}
483	
484		if !force {
485			var confirmed bool
486			form := NewAccessibleForm(
487				huh.NewGroup(
488					huh.NewConfirm().
489						Title(fmt.Sprintf("Stop session %s?", sessionID)).
490						Value(&confirmed),
491				),
492			)
493			if err := form.Run(); err != nil {
494				return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
495			}
496			if !confirmed {
497				fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
498				return nil
499			}
500		}
501	
502		return stopSessionAndPrint(ctx, cmd, state)
503	}
504	
505	// runStopAll stops all active sessions across all worktrees.
506	func runStopAll(ctx context.Context, cmd *cobra.Command, activeSessions []*strategy.SessionState, force bool) error {
507		if len(activeSessions) == 0 {
508			fmt.Fprintln(cmd.OutOrStdout(), "No active sessions.")
509			return nil
510		}
511	
512		if !force {
513			var confirmed bool
514			form := NewAccessibleForm(
515				huh.NewGroup(
516					huh.NewConfirm().
517						Title(fmt.Sprintf("Stop %d session(s)?", len(activeSessions))).
518						Value(&confirmed),
519				),
520			)
521			if err := form.Run(); err != nil {
522				return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
523			}
524			if !confirmed {
525				fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
526				return nil
527			}
528		}
529	
530		return stopSelectedSessions(ctx, cmd, activeSessions)
531	}
532	
533	// runStopMultiSelect shows a TUI multi-select for multiple active sessions.
534	func runStopMultiSelect(ctx context.Context, cmd *cobra.Command, activeSessions []*strategy.SessionState, force bool) error {
535		options := make([]huh.Option[string], len(activeSessions))
536		for i, s := range activeSessions {
537			wt := sessionWorktreeLabel(s)
538			label := fmt.Sprintf("%s · %s · %s", s.AgentType, wt, s.SessionID)
539			if s.LastPrompt != "" {
540				prompt := stringutil.TruncateRunes(s.LastPrompt, 40, "...")
541				label = fmt.Sprintf("%s · %q", label, prompt)
542			}
543			options[i] = huh.NewOption(label, s.SessionID)
544		}
545	
546		var selectedIDs []string
547		form := NewAccessibleForm(
548			huh.NewGroup(
549				huh.NewMultiSelect[string]().
550					Title("Select sessions to stop").
551					Description("Use space to select, enter to confirm.").
552					Options(options...).
553					Value(&selectedIDs),
554			),
555		)
556		if err := form.Run(); err != nil {
557			return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
558		}
559	
560		if len(selectedIDs) == 0 {
561			fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
562			return nil
563		}
564	
565		// Build a map for quick lookup
566		stateByID := make(map[string]*strategy.SessionState, len(activeSessions))
567		for _, s := range activeSessions {
568			stateByID[s.SessionID] = s
569		}
570	
571		// Confirm only if not forcing
572		if !force {
573			var confirmed bool
574			form := NewAccessibleForm(
575				huh.NewGroup(
576					huh.NewConfirm().
577						Title(fmt.Sprintf("Stop %d session(s)?", len(selectedIDs))).
578						Value(&confirmed),
579				),
580			)
581			if err := form.Run(); err != nil {
582				return handleFormCancellation(cmd.OutOrStdout(), "Stop", err)
583			}
584			if !confirmed {
585				fmt.Fprintln(cmd.OutOrStdout(), "Stop cancelled.")
586				return nil
587			}
588		}
589	
590		var toStop []*strategy.SessionState
591		for _, id := range selectedIDs {
592			if s, ok := stateByID[id]; ok {
593				toStop = append(toStop, s)
594			} else {
595				// Session was concurrently stopped between form render and confirmation.
596				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: session %s no longer found, skipping.\n", id)
597			}
598		}
599		if len(toStop) == 0 {
600			fmt.Fprintln(cmd.OutOrStdout(), "No sessions to stop.")
601			return nil
602		}
603		return stopSelectedSessions(ctx, cmd, toStop)
604	}
605	
606	// stopSelectedSessions stops each session in the list and prints a result line.
607	// Errors from individual sessions are accumulated so a single failure does not
608	// prevent remaining sessions from being stopped. Each failure is printed to stderr
609	// immediately so the user knows which sessions could not be stopped.
610	func stopSelectedSessions(ctx context.Context, cmd *cobra.Command, sessions []*strategy.SessionState) error {
611		var errs []error
612		for _, s := range sessions {
613			if err := stopSessionAndPrint(ctx, cmd, s); err != nil {
614				fmt.Fprintf(cmd.ErrOrStderr(), "✗ %v\n", err)
615				errs = append(errs, err)
616			}
617		}
618		return errors.Join(errs...)
619	}
620	
621	// stopSessionAndPrint stops a session and prints a summary line.
622	// Fields needed for output are read before calling markSessionEnded because
623	// markSessionEnded loads and operates on its own copy of the session state by ID —
624	// it does not update the caller's state pointer.
625	func stopSessionAndPrint(ctx context.Context, cmd *cobra.Command, state *strategy.SessionState) error {
626		sessionID := state.SessionID
627		lastCheckpointID := state.LastCheckpointID
628		stepCount := state.StepCount
629	
630		if err := markSessionEnded(ctx, nil, sessionID); err != nil {
631			return fmt.Errorf("failed to stop session %s: %w", sessionID, err)
632		}
633	
634		fmt.Fprintf(cmd.OutOrStdout(), "✓ Session %s stopped.\n", sessionID)
635		switch {
636		case lastCheckpointID != "":
637			fmt.Fprintf(cmd.OutOrStdout(), "  Checkpoint: %s\n", lastCheckpointID)
638		case stepCount > 0:
639			fmt.Fprintln(cmd.OutOrStdout(), "  Work will be captured in your next checkpoint.")
640		default:
641			fmt.Fprintln(cmd.OutOrStdout(), "  No work recorded.")
642		}
643		return nil
644	}
